void unit_test_buffer_appendf_successful_append_to_nonempty_buffer(void) {
    // Setup: create a buffer with initial data
    buffer_t *buf = helper_make_buffer_with_data("Hello");
    TEST_ASSERT_NOT_NULL(buf);

    // Test: append formatted string
